//! `emoji.tsv` is generated by `scripts/generate-emoji-data.py`.

use std::sync::OnceLock;

const DATA: &str = include_str!("emoji.tsv");

pub const DEFAULT_REACTIONS: [&str; 6] = ["👍", "🙌", "😂", "❤️", "🔥", "👀"];
pub const QUICK_COUNT: usize = DEFAULT_REACTIONS.len();
pub const RECENT_MAX: usize = 24;

const GROUPS: [(u8, &str); 9] = [
    (0, "Smileys & Emotion"),
    (1, "People & Body"),
    (3, "Animals & Nature"),
    (4, "Food & Drink"),
    (5, "Travel & Places"),
    (6, "Activities"),
    (7, "Objects"),
    (8, "Symbols"),
    (9, "Flags"),
];

struct Entry {
    group: u8,
    emoji: &'static str,
    labels: Vec<(&'static str, Vec<&'static str>)>,
    tags: Vec<&'static str>,
    tag_words: Vec<&'static str>,
}

fn entries() -> &'static [Entry] {
    static ENTRIES: OnceLock<Vec<Entry>> = OnceLock::new();
    ENTRIES.get_or_init(|| {
        DATA.lines()
            .filter_map(|line| {
                let mut cols = line.split('\t');
                let (group, emoji, labels) = (cols.next()?, cols.next()?, cols.next()?);
                let tags = cols.next().unwrap_or("");
                Some(Entry {
                    group: group.parse().ok()?,
                    emoji,
                    labels: labels.split('|').map(|l| (l, words(l).collect())).collect(),
                    tags: tags.split('|').collect(),
                    tag_words: words(tags).collect(),
                })
            })
            .collect()
    })
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct EmojiGroup {
    pub name: &'static str,
    pub emojis: Vec<&'static str>,
}

pub fn groups() -> Vec<EmojiGroup> {
    GROUPS
        .iter()
        .map(|&(id, name)| EmojiGroup {
            name,
            emojis: entries()
                .iter()
                .filter(|e| e.group == id)
                .map(|e| e.emoji)
                .collect(),
        })
        .filter(|g| !g.emojis.is_empty())
        .collect()
}

/// Ukrainian names mix ’ and ʼ; keyboards type '. The generator writes ' too.
fn normalize(text: &str) -> String {
    text.to_lowercase().replace(['’', 'ʼ'], "'")
}

fn words(text: &str) -> impl Iterator<Item = &str> {
    text.split(|c: char| !c.is_alphanumeric() && c != '\'')
        .filter(|w| !w.is_empty())
}

/// Lower is better; names with fewer words beyond the query rank first, so "heart" finds the
/// plain hearts before "heart with arrow".
fn rank(entry: &Entry, query: &str, tokens: &[String]) -> Option<(u8, usize)> {
    let has = |ws: &[&str], t: &String| ws.iter().any(|w| w.starts_with(t.as_str()));
    // Tags like "+1" and "✓" lose their meaning once split into words, so an exact tag wins then.
    let symbolic = words(query).map(str::len).sum::<usize>() < query.replace(' ', "").len();
    let tag_rank = if symbolic { (0, 1) } else { (1, usize::MAX) };
    let mut best = entry.tags.contains(&query).then_some(tag_rank);
    for (label, label_words) in &entry.labels {
        let score = if *label == query {
            (0, 0)
        } else if tokens.iter().all(|t| has(label_words, t)) {
            (1, label_words.len().saturating_sub(tokens.len()))
        } else {
            continue;
        };
        best = Some(best.map_or(score, |b| b.min(score)));
    }
    best.or_else(|| {
        tokens
            .iter()
            .all(|t| entry.labels.iter().any(|(_, ws)| has(ws, t)) || has(&entry.tag_words, t))
            .then_some((2, 0))
    })
}

pub fn search(query: &str, limit: usize) -> Vec<&'static str> {
    let query = normalize(query.trim());
    // A pasted ❤ or 👍️ differs from the catalog key only by the U+FE0F presentation selector.
    let bare = |s: &str| s.replace('\u{FE0F}', "");
    let pasted = bare(&query);
    if let Some(entry) = entries().iter().find(|e| bare(e.emoji) == pasted) {
        return std::iter::once(entry.emoji).take(limit).collect();
    }
    let tokens: Vec<String> = words(&query).map(str::to_string).collect();
    if tokens.is_empty() {
        return entries()
            .iter()
            .filter(|e| !query.is_empty() && e.tags.contains(&query.as_str()))
            .map(|e| e.emoji)
            .take(limit)
            .collect();
    }
    let mut hits: Vec<((u8, usize), usize, &'static str)> = entries()
        .iter()
        .enumerate()
        .filter_map(|(i, e)| rank(e, &query, &tokens).map(|r| (r, i, e.emoji)))
        .collect();
    hits.sort_unstable();
    hits.into_iter().take(limit).map(|(.., e)| e).collect()
}

pub fn remember(mut recent: Vec<String>, key: &str) -> Vec<String> {
    recent.retain(|k| k != key);
    recent.insert(0, key.to_string());
    recent.truncate(RECENT_MAX);
    recent
}

pub fn quick(recent: &[String]) -> Vec<String> {
    let mut out: Vec<String> = Vec::with_capacity(QUICK_COUNT);
    for key in recent.iter().map(String::as_str).chain(DEFAULT_REACTIONS) {
        if out.len() == QUICK_COUNT {
            break;
        }
        if !out.iter().any(|k| k == key) {
            out.push(key.to_string());
        }
    }
    out
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn groups_cover_all_data_without_components() {
        let groups = groups();
        assert_eq!(groups.len(), 9);
        let total: usize = groups.iter().map(|g| g.emojis.len()).sum();
        assert_eq!(total, entries().len());
        assert!(total > 1500);
        assert_eq!(groups[0].emojis[0], "😀");
    }

    #[test]
    fn keys_match_what_other_clients_send() {
        let all: Vec<&str> = entries().iter().map(|e| e.emoji).collect();
        for key in DEFAULT_REACTIONS {
            assert!(all.contains(&key), "{key} missing");
        }
        assert!(!all.contains(&"👍\u{FE0F}"));
    }

    #[test]
    fn search_in_three_languages() {
        for query in ["fire", "вогонь", "огонь"] {
            assert_eq!(search(query, 5)[0], "🔥", "{query}");
        }
        for query in ["red heart", "серце", "сердце"] {
            assert!(search(query, 10).contains(&"❤️"), "{query}");
        }
        assert_eq!(search("Thumbs Up", 3)[0], "👍");
    }

    #[test]
    fn apostrophe_variants_match() {
        assert!(!DATA.contains(['’', 'ʼ']));
        for query in ["п'яний", "п’яний", "пʼяний"] {
            assert!(!search(query, 5).is_empty(), "{query}");
        }
    }

    #[test]
    fn literal_emoji_and_symbol_tags() {
        assert_eq!(search("❤", 5), vec!["❤️"]);
        assert_eq!(search("👍\u{FE0F}", 5), vec!["👍"]);
        assert_eq!(search("+1", 3)[0], "👍");
        assert_eq!(search("-1", 3)[0], "👎");
        assert!(search("✓", 5).contains(&"✅"));
    }

    #[test]
    fn search_by_keyword_and_prefix() {
        assert!(search("lol", 20).contains(&"😂"));
        assert!(search("thum", 5).contains(&"👍"));
        assert!(search("  ", 5).is_empty());
        assert!(search("zzzzqqq", 5).is_empty());
        assert_eq!(search("🔥", 5), vec!["🔥"]);
        assert!(search("🔥", 0).is_empty());
        assert_eq!(search("heart", 3).len(), 3);
    }

    #[test]
    fn remember_moves_to_front_and_caps() {
        let recent = remember(vec!["👍".into(), "🔥".into()], "🔥");
        assert_eq!(recent, vec!["🔥", "👍"]);
        let mut many = Vec::new();
        for e in search("face", 40) {
            many = remember(many, e);
        }
        assert_eq!(many.len(), RECENT_MAX);
    }

    #[test]
    fn quick_fills_with_defaults() {
        assert_eq!(quick(&[]), DEFAULT_REACTIONS);
        assert_eq!(
            quick(&["🎉".into(), "👍".into()]),
            vec!["🎉", "👍", "🙌", "😂", "❤️", "🔥"]
        );
    }
}
